using System;using System.Web;using System.Web.Services;using WebPortal.Assets.Classes;
namespace WebPortal.Assets{public partial class AssetReturn:System.Web.UI.Page{static AssetBAL S=>new AssetBAL();static long U=>Convert.ToInt64(HttpContext.Current.User.Identity.Name.ToString());protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static object Lookup(string type,int? parentID){return AssetBAL.Rows(S.Lookup(type,parentID));}[WebMethod]public static object List(){return AssetBAL.Rows(S.WithAssetIds(S.List("Return")));}[WebMethod]public static ApiResult Save(ReturnInput x){try{var result=S.Save("usp_Assets_ReturnAsset",x,U);S.ReconcileAllocationAvailability(x.AllocationID,U);return ApiResult.Ok(result);}catch(Exception ex){return ApiResult.Fail(ex.Message);}}}}
